"""Offline fixture configuration and a file-backed clock shared by test processes."""

import json
from pathlib import Path
from time import monotonic, sleep

from access_intake.capture import capture
from access_intake.extraction import INSTRUCTIONS, SCHEMA, extract
from access_intake.routing import route
from access_intake.store import ProcessingConfig


ROOT = Path(__file__).resolve().parents[1]
MOCKS = ROOT / "tests" / "mock_responses"
INPUTS = ROOT / "materials" / "requests"


def config():
    return ProcessingConfig(
        settings={
            "provider": "mock", "model": "fixture-v1", "endpoint": "offline://fixtures",
            "prompt": INSTRUCTIONS, "schema": SCHEMA, "parameters": {"temperature": 0},
            "extraction_version": "1", "routing_version": "1",
        },
        policy_bytes=(ROOT / "materials" / "office-policy.md").read_bytes(),
        policy_label="office-policy",
        fixtures={f"it-{number:03}.json": (MOCKS / f"it-{number:03}.json").read_bytes() for number in (1, 2)},
    )


def sources():
    return [capture(INPUTS / f"IT-{number:03}.json") for number in (1, 2)]


class SharedClock:
    def __init__(self, path):
        self.path = Path(path)

    def __call__(self):
        return float(self.path.read_text(encoding="utf-8"))

    def set(self, value):
        staged = self.path.with_suffix(".next")
        staged.write_text(str(value), encoding="utf-8")
        staged.replace(self.path)


def write_receipt(path, value):
    path = Path(path)
    staged = path.with_suffix(".next")
    staged.write_text(json.dumps(value), encoding="utf-8")
    staged.replace(path)


class FileGate:
    """Event-compatible test barrier; uses local files rather than sockets."""

    def __init__(self, path):
        self.path = Path(path)

    def set(self):
        self.path.write_text("ready", encoding="utf-8")

    def wait(self, timeout=15):
        deadline = monotonic() + timeout
        while not self.path.exists():
            if monotonic() >= deadline:
                raise TimeoutError("Test barrier was not released")
            sleep(0.01)
        return True


def saved_result(source, provider):
    result = extract(source, provider)
    if result["error"] is None:
        result.update(route(source, result["extraction"]))
    result["response_source"] = "mock"
    return result

"""Run the real CLI parser offline, injecting only clocks/provider fault gates."""

import json
from pathlib import Path
import runpy
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from test_mock_provider import offline_only
from worker_support import FileGate, MOCKS, SharedClock, write_receipt
from access_intake.providers import HeldResponse, MockProvider


def main():
    mode, directory, *argv = sys.argv[1:]
    directory = Path(directory)
    with offline_only():
        if mode == "module":
            sys.argv = ["access_intake", *argv]
            runpy.run_module("access_intake", run_name="__main__")
            return 0

        from access_intake.cli import main as cli_main

        def factory(claim):
            fixture = MOCKS / claim["document_id"].lower()
            if mode == "held" and claim["document_id"] == "IT-001.json":
                return MockProvider([HeldResponse(fixture, entered=FileGate(directory / "entered"), release=FileGate(directory / "release"))])
            if mode == "fail-once" and claim["document_id"] == "IT-001.json":
                marker = directory / "failed-once"
                if not marker.exists():
                    marker.write_text("injected", encoding="utf-8")
                    return MockProvider([ConnectionError("scripted first failure")])
            return MockProvider([fixture])

        def after_claim(claim):
            if mode == "stop-after-claim" and claim["document_id"] == "IT-002.json":
                write_receipt(directory / "claim.json", claim)
                FileGate(directory / "release").wait()

        kwargs = {"clock": SharedClock(directory / "clock.txt")}
        if mode in ("held", "fail-once", "stop-after-claim"):
            kwargs.update(provider_factory=factory, worker_hooks={"after_claim": after_claim})
        return cli_main(argv, **kwargs)


if __name__ == "__main__":
    sys.exit(main())

"""Present recorded errors with retry commands for the selected database."""

from pathlib import Path
import shlex
from typing import Any


def for_output(value: Any, database: str | Path) -> Any:
    """Copy a view while making its retry commands independent of input paths."""
    if isinstance(value, list):
        return [for_output(item, database) for item in value]
    if not isinstance(value, dict):
        return value
    result = {key: for_output(item, database) for key, item in value.items()}
    if "retry_command" in result and "document_id" in result:
        result["retry_command"] = shlex.join([
            "python3", "-m", "access_intake", "--database", str(Path(database).resolve()),
            "retry", result["document_id"], "--force",
        ])
    return result

